input.command:
cd /workspace; python3 -c "
import json;d=json.load(open('grimoires/loa/a2a/sprint-1/adversarial-review.json'))
for f in d['findings'][2:]: print(json.dumps(f,indent=1))
print(json.dumps(d.get('metadata'),indent=1)[:3000])
print([k for k in d])
"; echo ====CFG; grep -nE "integrity_enforcement|security_audit:|code_review:|enabled:|guardrails:|input:|invisible_retrospective|companion_voice|adversarial" .loa.config.yaml | head -60

